package com.aivle.backend.journey;
import com.aivle.backend.common.entity.BaseEntity;import com.aivle.backend.project.entity.Project;import jakarta.persistence.*;import lombok.*;
@Entity(name="JourneyMarketingAssetVersion") @Table(name="marketing_asset_versions") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class JourneyMarketingAssetVersion extends BaseEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id",nullable=false)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="concept_version_id",nullable=false)private ConceptVersion conceptVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="asset_id",nullable=false)private JourneyMarketingAsset asset;@Column(nullable=false)private int versionNumber;@Column(nullable=false,length=300)private String title;@Column(name="content_json",nullable=false,columnDefinition="TEXT")private String contentJson;public static JourneyMarketingAssetVersion create(Project p,ConceptVersion c,JourneyMarketingAsset a,String title,String content){JourneyMarketingAssetVersion v=new JourneyMarketingAssetVersion();v.project=p;v.conceptVersion=c;v.asset=a;v.versionNumber=1;v.title=title;v.contentJson=content;return v;}}
